SET NAMES utf8mb4;

SET @development_database_schema_ok = (
    SELECT COUNT(*) = 12
    FROM information_schema.tables
    WHERE table_schema = DATABASE()
      AND table_name IN (
          'sys_user', 'sys_role', 'sys_user_role', 'sys_client', 'sys_menu',
          'app_user', 'app_auth_client', 'app_permission', 'app_role',
          'app_role_permission', 'app_user_role', 'av_quota_account'
      )
) AND EXISTS (
    SELECT 1
    FROM information_schema.columns
    WHERE table_schema = DATABASE()
      AND table_name = 'av_quota_account'
      AND column_name = 'used_balance'
);
SET @development_database_schema_guard_sql = IF(
    @development_database_schema_ok,
    'SELECT 1',
    'SELECT * FROM __development_database_schema_migrations_required'
);
PREPARE development_database_schema_guard_stmt FROM @development_database_schema_guard_sql;
EXECUTE development_database_schema_guard_stmt;
DEALLOCATE PREPARE development_database_schema_guard_stmt;

-- RunningHub facts must be supplied by forward migrations; this seed only guards the baseline.
