-- Require the exact RunningHub menu and app asset permission baseline before seeding development accounts.
SET @development_runninghub_permission_ok = (
    (SELECT COUNT(*) FROM sys_menu WHERE component IN ('aivideo/workflow-template/index','aivideo/runninghub-account/index')) = 2
    AND (SELECT COUNT(DISTINCT perms) FROM sys_menu WHERE perms IN ('aivideo:workflow-template:query','aivideo:workflow-template:add','aivideo:workflow-template:edit','aivideo:workflow-template:remove','aivideo:workflow-template:enable','aivideo:workflow-template:disable','aivideo:runninghub-account:query','aivideo:runninghub-account:add','aivideo:runninghub-account:edit','aivideo:runninghub-account:remove','aivideo:runninghub-account:enable','aivideo:runninghub-account:disable')) = 12
    AND NOT EXISTS (SELECT 1 FROM sys_menu WHERE component IN ('aivideo/discovery-home/index','aivideo/workflow-order/index'))
    AND NOT EXISTS (SELECT 1 FROM sys_menu WHERE perms IN ('aivideo:discover-home:query','aivideo:discover-home:edit','aivideo:workflow-template:inspect','aivideo:workflow-template:test','aivideo:runninghub-account:test','aivideo:runninghub-account:update-key','aivideo:workflow-order:query','aivideo:workflow-order:asset-access'))
    AND (SELECT COUNT(*) FROM app_permission WHERE permission_code IN ('aivideo:asset:query','aivideo:asset:upload','aivideo:asset:download')) = 3
    AND (SELECT COUNT(*) FROM app_role_permission WHERE role_id = 1000101 AND permission_id IN (1000032,1000033,1000034)) = 3
);
SET @development_runninghub_permission_guard_sql = IF(@development_runninghub_permission_ok, 'SELECT 1', 'SELECT * FROM __development_runninghub_permissions_required');
PREPARE development_runninghub_permission_guard_stmt FROM @development_runninghub_permission_guard_sql;
EXECUTE development_runninghub_permission_guard_stmt;
DEALLOCATE PREPARE development_runninghub_permission_guard_stmt;

