SET NAMES utf8mb4;

SET @seed_actor_id = 1761100000000000001;
SET @seed_now = NOW();
SET @seed_lock = GET_LOCK('ai_video:development_seed:20260810_01', 30);
SET @seed_lock_guard_sql = IF(
    @seed_lock = 1,
    'SELECT 1',
    'SELECT * FROM __development_seed_lock_timeout'
);
PREPARE seed_lock_guard_stmt FROM @seed_lock_guard_sql;
EXECUTE seed_lock_guard_stmt;
DEALLOCATE PREPARE seed_lock_guard_stmt;

START TRANSACTION;

