-- 创作端开发用户：creator / admin123。
INSERT INTO app_user (
    user_id, username, username_normalized, password_hash, phone_normalized,
    email_normalized, personal_tenant_id, display_name, status, must_change_password,
    credential_revision, identity_revision, permission_revision,
    created_by_type, created_by_id, updated_by_type, updated_by_id,
    create_time, update_time, del_flag
) VALUES (
    1761400000000009001, 'creator', 'creator',
    '$2a$10$7JB720yubVSZvUI0rEqK/.VqGOZTH.ulu33dHOiBE8ByOhJIrdAu2',
    NULL, NULL, 1761400000000009001, '本地创作者', 'active', 0,
    1, 1, 1, 'sys_user', @seed_actor_id, 'sys_user', @seed_actor_id,
    @seed_now, @seed_now, '0'
) ON DUPLICATE KEY UPDATE
    credential_revision = credential_revision + IF(password_hash <> VALUES(password_hash), 1, 0),
    identity_revision = identity_revision + IF(
        username <> VALUES(username)
        OR username_normalized <> VALUES(username_normalized)
        OR personal_tenant_id <> VALUES(personal_tenant_id)
        OR display_name <> VALUES(display_name)
        OR status <> VALUES(status)
        OR must_change_password <> VALUES(must_change_password)
        OR del_flag <> VALUES(del_flag),
        1,
        0
    ),
    username = VALUES(username),
    username_normalized = VALUES(username_normalized),
    password_hash = VALUES(password_hash),
    personal_tenant_id = VALUES(personal_tenant_id),
    display_name = VALUES(display_name),
    status = VALUES(status),
    must_change_password = VALUES(must_change_password),
    permission_revision = GREATEST(permission_revision, 1),
    updated_by_type = VALUES(updated_by_type),
    updated_by_id = VALUES(updated_by_id),
    update_time = VALUES(update_time),
    del_flag = VALUES(del_flag);

-- 用户端本地认证客户端；客户端密钥为空，只允许密码登录访问 /api/**。
INSERT INTO app_auth_client (
    id, client_id, client_key, client_secret_hash, grant_types, access_paths,
    ip_whitelist, token_timeout, active_timeout, client_revision, status,
    created_by_type, created_by_id, updated_by_type, updated_by_id,
    create_time, update_time, del_flag
) VALUES (
    1761400000000009002, 'desktop-web-local', 'desktop-web', NULL, 'password', '/api/**',
    NULL, 7200, 1800, 1, 'active', 'sys_user', @seed_actor_id,
    'sys_user', @seed_actor_id, @seed_now, @seed_now, '0'
) ON DUPLICATE KEY UPDATE
    client_revision = client_revision + IF(
        client_id <> VALUES(client_id)
        OR client_key <> VALUES(client_key)
        OR grant_types <> VALUES(grant_types)
        OR access_paths <> VALUES(access_paths)
        OR token_timeout <> VALUES(token_timeout)
        OR active_timeout <> VALUES(active_timeout)
        OR status <> VALUES(status)
        OR del_flag <> VALUES(del_flag),
        1,
        0
    ),
    client_id = VALUES(client_id),
    client_key = VALUES(client_key),
    grant_types = VALUES(grant_types),
    access_paths = VALUES(access_paths),
    token_timeout = VALUES(token_timeout),
    active_timeout = VALUES(active_timeout),
    status = VALUES(status),
    updated_by_type = VALUES(updated_by_type),
    updated_by_id = VALUES(updated_by_id),
    update_time = VALUES(update_time),
    del_flag = VALUES(del_flag);

