UPDATE app_role_permission actual
JOIN (
    SELECT 1000001 AS permission_id UNION ALL
    SELECT 1000004 UNION ALL SELECT 1000005 UNION ALL SELECT 1000006 UNION ALL
    SELECT 1000008 UNION ALL SELECT 1000009 UNION ALL SELECT 1000010 UNION ALL
    SELECT 1000011 UNION ALL SELECT 1000016 UNION ALL
    SELECT 1000017 UNION ALL SELECT 1000018 UNION ALL SELECT 1000019 UNION ALL
    SELECT 1000020 UNION ALL SELECT 1000021 UNION ALL SELECT 1000022 UNION ALL
    SELECT 1000023 UNION ALL SELECT 1000024 UNION ALL SELECT 1000025 UNION ALL
    SELECT 1000026 UNION ALL SELECT 1000027 UNION ALL SELECT 1000028 UNION ALL
    SELECT 1000029 UNION ALL SELECT 1000030 UNION ALL SELECT 1000031
) desired ON desired.permission_id = actual.permission_id
SET actual.status = 'active',
    actual.updated_by_type = 'sys_user',
    actual.updated_by_id = @seed_actor_id,
    actual.update_time = @seed_now
WHERE actual.role_id = 1000101
  AND actual.status <> 'active';

UPDATE app_role
SET role_revision = role_revision + IF(
        @creator_permission_seed_changed = 1
        OR @creator_role_seed_changed = 1
        OR @creator_role_permission_changed = 1,
        1,
        0
    ),
    updated_by_type = 'sys_user',
    updated_by_id = @seed_actor_id,
    update_time = @seed_now
WHERE role_id = 1000101;

SET @creator_user_role_changed = NOT EXISTS (
    SELECT 1
    FROM app_user_role
    WHERE user_id = 1761400000000009001
      AND role_id = 1000101
      AND status = 'active'
      AND valid_from IS NULL
      AND valid_until IS NULL
);

INSERT IGNORE INTO app_user_role (
    id, user_id, role_id, status, valid_from, valid_until,
    created_by_type, created_by_id, updated_by_type, updated_by_id,
    create_time, update_time
) VALUES (
    1761400000000009003, 1761400000000009001, 1000101, 'active', NULL, NULL,
    'sys_user', @seed_actor_id, 'sys_user', @seed_actor_id, @seed_now, @seed_now
);

UPDATE app_user_role
SET status = 'active',
    valid_from = NULL,
    valid_until = NULL,
    updated_by_type = 'sys_user',
    updated_by_id = @seed_actor_id,
    update_time = @seed_now
WHERE user_id = 1761400000000009001
  AND role_id = 1000101
  AND (status <> 'active' OR valid_from IS NOT NULL OR valid_until IS NOT NULL);

UPDATE app_user
SET permission_revision = permission_revision + IF(
        @creator_permission_seed_changed = 1
        OR @creator_role_seed_changed = 1
        OR @creator_role_permission_changed = 1
        OR @creator_user_role_changed = 1,
        1,
        0
    ),
    updated_by_type = 'sys_user',
    updated_by_id = @seed_actor_id,
    update_time = @seed_now
WHERE user_id = 1761400000000009001;

